import{E as e,F as t,q as n,w as r}from"./vue.runtime.esm-bundler-DZZTqpJU.js";t();var i={class:`markdown-body`},a={__name:`xpath`,setup(t,{expose:a}){return a({frontmatter:{}}),(t,a)=>(n(),r(`div`,i,[...a[0]||=[e(`<p><strong>XPath</strong> navigates an XML or HTML document as a tree. Every step has the form <code>axis::node-test[predicate]</code>, and most of it has a short form: <code>//div[@class=&quot;card&quot;]/a/@href</code> reads “the <code>href</code> of every <code>a</code> inside any <code>div</code> with class <code>card</code>”.</p><blockquote><p>⚠️ Browsers, Selenium and most scrapers implement <strong>XPath 1.0</strong>. <code>ends-with()</code>, <code>matches()</code>, <code>lower-case()</code> and <code>replace()</code> are 2.0+ and only work in tools like <code>xmllint</code>, Saxon or <code>lxml</code> with an XSLT 2.0 processor. Workarounds for 1.0 are given below.</p></blockquote><h2>🧭 Path Syntax</h2><table><thead><tr><th>XPath</th><th>Selects</th></tr></thead><tbody><tr><td><code>/</code></td><td>From the document root — an absolute path</td></tr><tr><td><code>//</code></td><td>Anywhere in the document, at any depth</td></tr><tr><td><code>.</code></td><td>The current (context) node</td></tr><tr><td><code>..</code></td><td>The parent of the context node</td></tr><tr><td><code>@attr</code></td><td>An attribute</td></tr><tr><td><code>*</code></td><td>Any element</td></tr><tr><td><code>@*</code></td><td>Any attribute</td></tr><tr><td><code>text()</code></td><td>The text nodes of an element</td></tr><tr><td><code>node()</code></td><td>Any node at all, text and comments included</td></tr><tr><td><code>[n]</code></td><td>The nth match — <strong>1-based</strong>, not 0-based</td></tr><tr><td><code>[last()]</code></td><td>The last match</td></tr><tr><td><code>a | b</code></td><td>The union of two expressions</td></tr></tbody></table><pre><code class="language-xpath">/html/body            (: absolute: the body of the page :)
//text()              (: every text node :)
./div/b               (: relative to the context node :)
(//p)[2]              (: the second p in the whole document :)
//p[2]                (: every p that is the second p of its parent :)
</code></pre><h2>🏷 Elements &amp; Attributes</h2><table><thead><tr><th>XPath</th><th>Description</th><th>CSS</th></tr></thead><tbody><tr><td><code>//E</code></td><td>Every <code>&lt;E&gt;</code> element</td><td><code>E</code></td></tr><tr><td><code>(//E)[2]</code></td><td>The second <code>&lt;E&gt;</code> in the document</td><td>—</td></tr><tr><td><code>//E[@A]</code></td><td><code>&lt;E&gt;</code> carrying attribute <code>A</code></td><td><code>E[A]</code></td></tr><tr><td><code>//E[@A=&quot;t&quot;]</code></td><td><code>&lt;E&gt;</code> where <code>A</code> is exactly <code>t</code></td><td><code>E[A=&#39;t&#39;]</code></td></tr><tr><td><code>//E[contains(@A,&quot;t&quot;)]</code></td><td><code>&lt;E&gt;</code> where <code>A</code> contains <code>t</code></td><td><code>E[A*=&#39;t&#39;]</code></td></tr><tr><td><code>//E[starts-with(@A,&quot;t&quot;)]</code></td><td><code>&lt;E&gt;</code> where <code>A</code> starts with <code>t</code></td><td><code>E[A^=&#39;t&#39;]</code></td></tr><tr><td><code>//E[substring(@A, string-length(@A)-2)=&quot;t&quot;]</code></td><td><code>&lt;E&gt;</code> where <code>A</code> ends with <code>t</code> (1.0 trick)</td><td><code>E[A$=&#39;t&#39;]</code></td></tr><tr><td><code>//E[ends-with(@A,&quot;t&quot;)]</code></td><td>The same, XPath 2.0+ only</td><td><code>E[A$=&#39;t&#39;]</code></td></tr><tr><td><code>//E[matches(@A,&quot;r&quot;)]</code></td><td><code>A</code> matches regex <code>r</code> (2.0+)</td><td>—</td></tr><tr><td><code>//E/@A</code></td><td>The value of attribute <code>A</code></td><td>—</td></tr><tr><td><code>//*/@A</code></td><td>Attribute <code>A</code> of any element</td><td>—</td></tr><tr><td><code>//E[@A2=&quot;t&quot;]/@A1</code></td><td><code>A1</code> where <code>A2</code> is <code>t</code></td><td>—</td></tr><tr><td><code>//E1[@id=&quot;I1&quot;] | //E2[@id=&quot;I2&quot;]</code></td><td>Either element</td><td><code>E1#I1, E2#I2</code></td></tr><tr><td><code>//E[@id=&quot;I1&quot; or @id=&quot;I2&quot;]</code></td><td><code>&lt;E&gt;</code> with either id</td><td><code>E#I1, E#I2</code></td></tr></tbody></table><h2>🆔 Id, Name, Class &amp; Language</h2><table><thead><tr><th>XPath</th><th>Description</th><th>CSS</th></tr></thead><tbody><tr><td><code>//*[@id=&quot;I&quot;]</code></td><td>The element with id <code>I</code></td><td><code>#I</code></td></tr><tr><td><code>//E[@id=&quot;I&quot;]</code></td><td><code>&lt;E&gt;</code> with id <code>I</code></td><td><code>E#I</code></td></tr><tr><td><code>//*[@name=&quot;N&quot;]</code></td><td>Any element named <code>N</code></td><td><code>[name=&#39;N&#39;]</code></td></tr><tr><td><code>//*[@name=&quot;N&quot;][@value=&quot;v&quot;]</code></td><td>Named <code>N</code> with value <code>v</code></td><td><code>[name=&#39;N&#39;][value=&#39;v&#39;]</code></td></tr><tr><td><code>//*[contains(concat(&quot; &quot;, normalize-space(@class), &quot; &quot;), &quot; C &quot;)]</code></td><td>Element with class <code>C</code> — the padding avoids matching <code>C2</code></td><td><code>.C</code></td></tr><tr><td><code>//E[contains(concat(&quot; &quot;, normalize-space(@class), &quot; &quot;), &quot; C &quot;)]</code></td><td><code>&lt;E&gt;</code> with class <code>C</code></td><td><code>E.C</code></td></tr><tr><td><code>//E[@lang=&quot;L&quot; or starts-with(@lang, concat(&quot;L&quot;,&quot;-&quot;))]</code></td><td><code>&lt;E&gt;</code> in language <code>L</code> or a subcode</td><td><code>E[lang|=&#39;L&#39;]</code></td></tr></tbody></table><h2>📝 Text &amp; Links</h2><table><thead><tr><th>XPath</th><th>Description</th><th>CSS</th></tr></thead><tbody><tr><td><code>//*[.=&quot;t&quot;]</code></td><td>Element whose whole text is exactly <code>t</code></td><td>—</td></tr><tr><td><code>//E[contains(text(),&quot;t&quot;)]</code></td><td><code>&lt;E&gt;</code> with a text node containing <code>t</code></td><td>—</td></tr><tr><td><code>//E[contains(.,&quot;t&quot;)]</code></td><td><code>&lt;E&gt;</code> whose text, descendants included, contains <code>t</code></td><td>—</td></tr><tr><td><code>//E[normalize-space()=&quot;t&quot;]</code></td><td>Exact text, ignoring surrounding whitespace</td><td>—</td></tr><tr><td><code>//a</code></td><td>Every link</td><td><code>a</code></td></tr><tr><td><code>//a[.=&quot;t&quot;]</code></td><td>The link labelled exactly <code>t</code></td><td>—</td></tr><tr><td><code>//a[@href=&quot;url&quot;]</code></td><td>The link pointing at <code>url</code></td><td><code>a[href=&#39;url&#39;]</code></td></tr><tr><td><code>//a[.=&quot;t&quot;]/@href</code></td><td>The URL behind the label <code>t</code></td><td>—</td></tr><tr><td><code>//a[starts-with(@href,&quot;https&quot;)]</code></td><td>Secure links only</td><td><code>a[href^=&#39;https&#39;]</code></td></tr></tbody></table><h2>👪 Parents &amp; Children</h2><table><thead><tr><th>XPath</th><th>Description</th><th>CSS</th></tr></thead><tbody><tr><td><code>//E/*[1]</code></td><td>First child of <code>&lt;E&gt;</code></td><td><code>E &gt; *:first-child</code></td></tr><tr><td><code>//E/*[last()]</code></td><td>Last child of <code>&lt;E&gt;</code></td><td><code>E &gt; *:last-child</code></td></tr><tr><td><code>//E[1]</code></td><td>Each <code>&lt;E&gt;</code> that is the first of its type in its parent</td><td><code>E:first-of-type</code></td></tr><tr><td><code>//E[last()]</code></td><td>Last <code>&lt;E&gt;</code> of its type</td><td><code>E:last-of-type</code></td></tr><tr><td><code>//E[2]</code></td><td>Second <code>&lt;E&gt;</code> of its type</td><td><code>E:nth-of-type(2)</code></td></tr><tr><td><code>//*[2][name()=&quot;E&quot;]</code></td><td>Second child, if it is an <code>&lt;E&gt;</code></td><td><code>E:nth-child(2)</code></td></tr><tr><td><code>//E[last()-1]</code></td><td>Second-to-last <code>&lt;E&gt;</code> of its type</td><td><code>E:nth-last-of-type(2)</code></td></tr><tr><td><code>//E/..</code></td><td>The parent of <code>&lt;E&gt;</code></td><td>—</td></tr><tr><td><code>//div/form/parent::*</code></td><td>Every element that has a form child</td><td><code>div:has(&gt; form)</code></td></tr><tr><td><code>//*[@id=&quot;I&quot;]//E</code></td><td><code>&lt;E&gt;</code> anywhere under id <code>I</code></td><td><code>#I E</code></td></tr><tr><td><code>//E[count(*)=0]</code></td><td><code>&lt;E&gt;</code> with no element children</td><td><code>E:empty</code></td></tr><tr><td><code>//E[count(*)=1]</code></td><td><code>&lt;E&gt;</code> with exactly one child</td><td>—</td></tr><tr><td><code>//E[count(preceding-sibling::*)+count(following-sibling::*)=0]</code></td><td><code>&lt;E&gt;</code> that is an only child</td><td><code>E:only-child</code></td></tr><tr><td><code>//E[count(../E)=1]</code></td><td><code>&lt;E&gt;</code> with no <code>&lt;E&gt;</code> siblings</td><td><code>E:only-of-type</code></td></tr><tr><td><code>//E1[E2 and not(*[not(self::E2)])]</code></td><td><code>&lt;E1&gt;</code> whose only children are <code>&lt;E2&gt;</code></td><td>—</td></tr><tr><td><code>//E[position() mod N = M + 1]</code></td><td>Every Nth element, offset by M</td><td><code>E:nth-child(Nn+M)</code></td></tr></tbody></table><h2>👥 Siblings</h2><table><thead><tr><th>XPath</th><th>Description</th><th>CSS</th></tr></thead><tbody><tr><td><code>//E2/following-sibling::E1</code></td><td>Every <code>&lt;E1&gt;</code> after a sibling <code>&lt;E2&gt;</code></td><td><code>E2 ~ E1</code></td></tr><tr><td><code>//E2/following-sibling::*[1][name()=&quot;E1&quot;]</code></td><td><code>&lt;E1&gt;</code> immediately after <code>&lt;E2&gt;</code></td><td><code>E2 + E1</code></td></tr><tr><td><code>//E2/following-sibling::*[2][name()=&quot;E1&quot;]</code></td><td><code>&lt;E1&gt;</code> two siblings after <code>&lt;E2&gt;</code></td><td><code>E2 + * + E1</code></td></tr><tr><td><code>//E/following-sibling::*[1]</code></td><td>Whatever follows <code>&lt;E&gt;</code> directly</td><td><code>E + *</code></td></tr><tr><td><code>//E2/preceding-sibling::E1</code></td><td>Every <code>&lt;E1&gt;</code> before a sibling <code>&lt;E2&gt;</code></td><td>—</td></tr><tr><td><code>//E2/preceding-sibling::*[1][name()=&quot;E1&quot;]</code></td><td><code>&lt;E1&gt;</code> immediately before <code>&lt;E2&gt;</code></td><td>—</td></tr><tr><td><code>//E/preceding-sibling::*[1]</code></td><td>Whatever precedes <code>&lt;E&gt;</code> directly</td><td>—</td></tr></tbody></table><h2>📊 Tables &amp; Form State</h2><table><thead><tr><th>XPath</th><th>Description</th><th>CSS</th></tr></thead><tbody><tr><td><code>//*[@id=&quot;T&quot;]//tr[3]//td[2]</code></td><td>Third row, second cell</td><td><code>#T tr:nth-child(3) td:nth-child(2)</code></td></tr><tr><td><code>//td[preceding-sibling::td=&quot;t&quot;]</code></td><td>The cell right after the one reading <code>t</code></td><td>—</td></tr><tr><td><code>//td[preceding-sibling::td[contains(.,&quot;t&quot;)]]</code></td><td>Cells following one containing <code>t</code></td><td><code>td:has(~ td)</code></td></tr><tr><td><code>//table[count(tr)=1 and count(tr/td)=2]</code></td><td>Tables with one row and two columns</td><td>—</td></tr><tr><td><code>//table/tr[last()]</code></td><td>The last row of a table</td><td><code>table tr:last-child</code></td></tr><tr><td><code>//E[@disabled]</code></td><td>A disabled control</td><td><code>E:disabled</code></td></tr><tr><td><code>//E[not(@disabled)]</code></td><td>A control that is not disabled</td><td><code>E:enabled</code></td></tr><tr><td><code>//*[@checked]</code></td><td>A checked checkbox or radio</td><td><code>:checked</code></td></tr></tbody></table><h2>🧮 Functions</h2><h3>Strings</h3><table><thead><tr><th>Function</th><th>Returns</th></tr></thead><tbody><tr><td><code>contains(haystack, needle)</code></td><td>True when the first string contains the second</td></tr><tr><td><code>starts-with(haystack, needle)</code></td><td>True when it starts with it</td></tr><tr><td><code>concat(s1, s2, …)</code></td><td>The strings joined together</td></tr><tr><td><code>normalize-space(s)</code></td><td>The string with runs of whitespace collapsed and trimmed</td></tr><tr><td><code>string-length(s)</code></td><td>The number of characters</td></tr><tr><td><code>substring(s, start [, length])</code></td><td>A slice — <strong>1-based</strong></td></tr><tr><td><code>substring-before(haystack, needle)</code></td><td>Everything before the first occurrence</td></tr><tr><td><code>substring-after(haystack, needle)</code></td><td>Everything after it</td></tr><tr><td><code>translate(s, from, to)</code></td><td>Characters mapped one by one — the 1.0 way to fold case</td></tr></tbody></table><h3>Numbers, logic &amp; nodes</h3><table><thead><tr><th>Function</th><th>Returns</th></tr></thead><tbody><tr><td><code>count(node-set)</code></td><td>How many nodes matched</td></tr><tr><td><code>sum(node-set)</code></td><td>The sum of their numeric values</td></tr><tr><td><code>position()</code></td><td>The index of the context node within its step</td></tr><tr><td><code>last()</code></td><td>The size of the context — so <code>[last()]</code> is the final node</td></tr><tr><td><code>name([node-set])</code></td><td>The qualified name of the first node</td></tr><tr><td><code>namespace-uri([node-set])</code></td><td>Its namespace URI</td></tr><tr><td><code>lang(s)</code></td><td>True when the node is in that language</td></tr><tr><td><code>not(expr)</code></td><td>The negation</td></tr><tr><td><code>true()</code> / <code>false()</code></td><td>Boolean constants</td></tr><tr><td><code>boolean(expr)</code> / <code>string(o)</code> / <code>number(o)</code></td><td>Type conversions</td></tr><tr><td><code>ceiling(n)</code> / <code>floor(n)</code> / <code>round(n)</code></td><td>Rounding</td></tr></tbody></table><blockquote><p>💡 Case-insensitive matching in XPath 1.0: <code>//E[contains(translate(@A,&quot;ABCDEFGHIJKLMNOPQRSTUVWXYZ&quot;,&quot;abcdefghijklmnopqrstuvwxyz&quot;), &quot;t&quot;)]</code></p></blockquote><h2>🧭 Axes</h2><table><thead><tr><th>Axis</th><th>Short form</th><th>Selects</th></tr></thead><tbody><tr><td><code>child</code></td><td><em>(default)</em></td><td>The direct children of the context node</td></tr><tr><td><code>descendant</code></td><td><code>//</code></td><td>Every node below the context node</td></tr><tr><td><code>descendant-or-self</code></td><td><code>//</code></td><td>The context node and everything below it</td></tr><tr><td><code>parent</code></td><td><code>..</code></td><td>The single parent node</td></tr><tr><td><code>ancestor</code></td><td>—</td><td>Parent, grandparent, up to the root</td></tr><tr><td><code>ancestor-or-self</code></td><td>—</td><td>The same, including the context node</td></tr><tr><td><code>following</code></td><td>—</td><td>Everything after the node in document order, except descendants</td></tr><tr><td><code>following-sibling</code></td><td>—</td><td>Later siblings under the same parent</td></tr><tr><td><code>preceding</code></td><td>—</td><td>Everything before it, except its ancestors</td></tr><tr><td><code>preceding-sibling</code></td><td>—</td><td>Earlier siblings under the same parent</td></tr><tr><td><code>attribute</code></td><td><code>@</code></td><td>The attributes of the node</td></tr><tr><td><code>self</code></td><td><code>.</code></td><td>The context node itself</td></tr></tbody></table><pre><code class="language-xpath">//td[.=&quot;Total&quot;]/ancestor::table          (: the table a cell belongs to :)
//h2[.=&quot;Specs&quot;]/following-sibling::ul[1] (: the list after a heading :)
//input[@name=&quot;q&quot;]/ancestor-or-self::form (: the form wrapping a field :)
</code></pre><h2>🧠 Worked Examples</h2><pre><code class="language-xpath">//hr[@class=&quot;edge&quot; and position()=1]
(: the first hr of class &#39;edge&#39; under each parent :)

//table[parent::div[@class=&quot;pad&quot;] and not(@id)]//a
(: links in unnamed tables inside a padded div :)

/html/body/div/*[preceding-sibling::h4]
(: whatever comes after an h4 :)

//tr/td[font[@class=&quot;head&quot; and text()=&quot;TRACK&quot;]]
(: cells whose font child says TRACK :)

//*[count(*)=3]
(: elements with exactly three children :)

//rdf:Seq/rdf:li/em:id
(: namespaced elements — the prefixes must be bound by the host tool :)

//var | //acronym
(: a union of two node sets :)
</code></pre><h2>🛠 Running XPath</h2><pre><code class="language-javascript">// browser devtools console
$x(&#39;//a[contains(@href, &quot;docs&quot;)]&#39;);

// plain DOM API
document.evaluate(&#39;//h1&#39;, document, null, XPathResult.ANY_TYPE, null).iterateNext();
</code></pre><pre><code class="language-bash"># from the shell, over XML or HTML
xmllint --xpath &#39;//book/title/text()&#39; catalog.xml
xmllint --html --xpath &#39;//a/@href&#39; page.html 2&gt;/dev/null
</code></pre><pre><code class="language-python">from lxml import html
tree = html.parse(&#39;page.html&#39;)
tree.xpath(&#39;//div[@class=&quot;card&quot;]/a/@href&#39;)
</code></pre><pre><code class="language-python"># Selenium and Playwright both accept XPath locators
driver.find_element(By.XPATH, &#39;//button[normalize-space()=&quot;Save&quot;]&#39;)
page.locator(&#39;xpath=//button[normalize-space()=&quot;Save&quot;]&#39;).click()
</code></pre><h2>⚠️ Notes</h2><ul><li><strong>Indexes start at 1.</strong> <code>[0]</code> never matches anything.</li><li><strong><code>//E[1]</code> is per-parent</strong>, <code>(//E)[1]</code> is document-wide — the single most common XPath bug.</li><li><strong>Namespaced documents</strong> need prefixes registered with the host library; in XPath 1.0 a common workaround is <code>//*[local-name()=&quot;title&quot;]</code>.</li><li><strong><code>//</code> is expensive</strong> on large documents; anchor the path when you can.</li><li><strong>Prefer text matching with <code>normalize-space()</code></strong> — HTML is full of stray whitespace and line breaks.</li></ul><h2>📚 Resources</h2><ul><li><a href="https://developer.mozilla.org/en-US/docs/Web/XML/XPath">MDN — XPath</a></li><li><a href="https://developer.mozilla.org/en-US/docs/Web/XML/XPath/Reference/Functions">MDN — XPath functions</a></li><li><a href="https://www.w3.org/TR/xpath-10/">XPath 1.0 specification</a></li><li><a href="http://xpath.alephzarro.com/content/cheatsheet.html">XPath cheat sheet (alephzarro)</a></li></ul><p>Credit to the original author: <a href="https://gist.github.com/jmaccabee/550a0b9fcfdc7e6b170cd34c6ec7bc56">https://gist.github.com/jmaccabee/550a0b9fcfdc7e6b170cd34c6ec7bc56</a></p>`,38)]]))}};export{a as default};